(function(root){
  const subjects=['국어','수학','영어','한국사','사회','과학','체육','예술','기술·가정','정보','제2외국어','한문'];
  const headers=/(교과|과목|이수|학점|단위|석차|성취도|원점수|평균|표준편차|수강자)/g;
  const cleanup=s=>s.replace(/[|_│┃]/g,' ').replace(/[^가-힣A-Za-z0-9().,·+\-\s]/g,' ').replace(/\s+/g,' ').trim();
  function inferSubject(line){return subjects.find(s=>line.includes(s.replace('·','')))||subjects.find(s=>line.includes(s))||''}
  function parseLine(raw,index){const line=cleanup(raw),numbers=[...line.matchAll(/(?<![A-Za-z가-힣])(\d+(?:\.\d+)?)(?![A-Za-z가-힣])/g)].map(m=>Number(m[1]));if(line.length<4||headers.test(line)&&numbers.length<3)return null;headers.lastIndex=0;let grade=null,semester=null,start=0;const explicit=line.match(/([123])\s*학년\s*([12])\s*학기/);if(explicit){grade=+explicit[1];semester=+explicit[2]}else if(numbers.length>=4&&[1,2,3].includes(numbers[0])&&[1,2].includes(numbers[1])){grade=numbers[0];semester=numbers[1];start=2}const achievement=(line.match(/(?:^|\s)([ABCDE])(?:\s|$|\()/i)||[])[1]?.toUpperCase()||'';const tail=numbers.slice(start);let credits=null,rankGrade=null,rawScore=null,mean=null,stddev=null;if(tail.length){credits=tail.find(n=>n>0&&n<=12)??null;const creditIndex=tail.indexOf(credits);rankGrade=tail.slice(creditIndex+1).find(n=>Number.isInteger(n)&&n>=1&&n<=9)??null;const scores=tail.filter(n=>n>12&&n<=100);[rawScore,mean,stddev]=scores}const subject=inferSubject(line);let name=line.replace(/([123])\s*학년\s*([12])\s*학기/,'').replace(headers,' ').replace(/(?<![A-Za-z가-힣])\d+(?:\.\d+)?(?![A-Za-z가-힣])/g,' ').replace(/(?:^|\s)[ABCDE](?:\s|$)/ig,' ').replace(/\s+/g,' ').trim();if(subject)name=name.replace(subject,'').trim()||subject;const evidence=[grade,semester,subject,name,credits,rankGrade||achievement].filter(Boolean).length;if(!name||evidence<3)return null;return {sourceLine:index+1,raw:line,grade:grade||1,semester:semester||1,subject:subject||'기타',name,credits,rankGrade,achievement,rawScore,mean,stddev,type:achievement?'진로선택':'공통과목',confidence:Math.min(98,35+evidence*9)} }
  function parse(text){const seen=new Set();return String(text||'').split(/\r?\n/).map(parseLine).filter(Boolean).filter(r=>{const key=`${r.grade}|${r.semester}|${r.name}|${r.rankGrade}|${r.achievement}`;if(seen.has(key))return false;seen.add(key);return true})}
  const api={parse,parseLine,cleanup};root.TranscriptParser=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
